215:     pub fn lookup<F>(
216:         &mut self,
217:         namespace_bytes: &[u8],
218:         salt: Option<&str>,
219:         tokens: &[u32],
220:         mut is_resident: F,
221:     ) -> LookupOutcome<V>
222:     where
223:         F: FnMut(StateKey, &V) -> bool,
224:     {
225:         let mut outcome = LookupOutcome::default();
226:         if !self.enabled {
227:             return outcome;
228:         }
229:         let domain = CacheDomain::new(namespace_bytes, salt);
230:         let Some(lengths) = self.entries.get(&domain) else {
231:             return outcome;
232:         };
233:         for (&length, roots) in lengths.range(..=tokens.len()).rev() {
234:             let prefix = &tokens[..length];
235:             let blocks = self.block_hashes(prefix);
236:             let root = Self::root(&domain, length, &blocks);
237:             let Some(bucket) = roots.get(&root) else {
238:                 continue;
239:             };
240:             for entry in bucket {
241:                 if entry.block_hashes.as_ref() != blocks.as_slice()
242:                     || entry.tokens.as_ref() != prefix
243:                 {
244:                     outcome.hash_collisions += 1;
245:                     continue;
246:                 }
247:                 if is_resident(entry.key, &entry.value) {
248:                     self.lru.retain(|candidate| *candidate != entry.key);
249:                     self.lru.push_back(entry.key);
250:                     outcome.hit = Some(PrefixCacheHit {
251:                         value: entry.value.clone(),
252:                         reused_tokens: length,
253:                     });
254:                     return outcome;
255:                 }
256:                 outcome.stale_entries += 1;
257:             }

