201:     /// Publish successful completion and release every coalesced correlation.
202:     ///
203:     /// # Errors
204:     ///
205:     /// Rejects unknown, stale, or forged leases without changing admitted work.
206:     pub fn commit(&mut self, lease: &TransferLease) -> Result<Vec<u64>, CompletionError> {
207:         let key = self.validate_lease(lease)?;
208:         let work = self
209:             .pending
210:             .remove(&key)
211:             .ok_or(CompletionError::UnknownLease)?;
212:         for correlation in &work.correlations {
213:             self.correlations.remove(correlation);
214:         }
215:         self.stats.committed += 1;
216:         self.stats.completed_correlations += work.correlations.len() as u64;
217:         Ok(work.correlations)

220:     /// Abort an active lease, optionally requeueing it within the retry budget.
221:     ///
222:     /// # Errors
223:     ///
224:     /// Rejects invalid leases. A request to retry beyond the configured budget
225:     /// fails the work closed and returns [`CompletionError::RetryBudgetExhausted`].
226:     pub fn abort(
227:         &mut self,
228:         lease: &TransferLease,
229:         retry: bool,
230:     ) -> Result<Vec<u64>, CompletionError> {
231:         let key = self.validate_lease(lease)?;
232:         self.stats.aborted += 1;
233:         if retry {
234:             let work = self
235:                 .pending
236:                 .get_mut(&key)
237:                 .ok_or(CompletionError::UnknownLease)?;
238:             if work.attempt > self.config.max_retries {
239:                 let correlations = self.fail_key(key);
240:                 return Err(if correlations.is_empty() {
241:                     CompletionError::UnknownLease
242:                 } else {
243:                     CompletionError::RetryBudgetExhausted
244:                 });
245:             }
246:             work.lease_id = None;
247:             self.queue.push_back(key);
248:             self.stats.retried += 1;
249:             return Ok(Vec::new());
250:         }
251:         Ok(self.fail_key(key))
252:     }
