254:     fn validate_lease(&self, lease: &TransferLease) -> Result<StateKey, CompletionError> {
255:         let key = lease.identity.state_key();
256:         let work = self
257:             .pending
258:             .get(&key)
259:             .ok_or(CompletionError::UnknownLease)?;
260:         if work.identity != lease.identity
261:             || work.lease_id != Some(lease.lease_id)
262:             || work.attempt != lease.attempt
263:         {
264:             return Err(CompletionError::LeaseMismatch);
265:         }
266:         Ok(key)
267:     }
